#include "drv_disp_Symphony6_reg.h"

static void DRV_DispRegWr(ulong reg_addr, MT_U32 data)
{
  ulong tempAddr = reg_addr;
  *(volatile MT_U32 *)tempAddr = data;
}

static MT_U32 DRV_DispRegRd(ulong reg_addr)
{
  unsigned long tempAddr = reg_addr;

  return *(volatile MT_U32 *)tempAddr;
}

